//! The id of a builtin (ADR-032 step 2): a `u16` index into a generated, sorted table of every
//! overload id (`Record.Insert#2`) of the catalog, of the registered natives, and of the ids the
//! lowering invents. The IR carries this, the VM dispatches on it, and the name stays available for
//! messages.
//!
//! The table is `builtin_ids.rs`, generated by `cargo run -p al-builtins --example gen_builtin_ids`
//! and checked in; the test `builtin_ids_current` fails when it is stale. Every id also has a
//! constant in [`ids`] (`ids::RECORD_INSERT_2`) usable in a `match`.

use serde::{Deserialize, Serialize};

/// What kind of VM-run builtin an id belongs to, so the VM picks a path without reading the name.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Class {
    /// `Codeunit.Run#n`.
    CodeunitRun,
    /// `Xmlport.*`.
    Xmlport,
    /// `Report.*`.
    Report,
    /// `FilterPageBuilder.*`.
    FilterPageBuilder,
    /// `InStream.Read*`: a read into a Text or Code variable is fitted to its length.
    InStreamRead,
    /// Everything else.
    Other,
}

impl Class {
    /// The variant name, for the generated table.
    pub fn variant(self) -> &'static str {
        match self {
            Class::CodeunitRun => "CodeunitRun",
            Class::Xmlport => "Xmlport",
            Class::Report => "Report",
            Class::FilterPageBuilder => "FilterPageBuilder",
            Class::InStreamRead => "InStreamRead",
            Class::Other => "Other",
        }
    }
}

/// The class of the id with this name.
pub fn class_of(name: &str) -> Class {
    if name.starts_with("Codeunit.Run#") {
        Class::CodeunitRun
    } else if name.starts_with("Xmlport.") {
        Class::Xmlport
    } else if name.starts_with("Report.") {
        Class::Report
    } else if name.starts_with("FilterPageBuilder.") {
        Class::FilterPageBuilder
    } else if name.starts_with("InStream.Read") {
        Class::InStreamRead
    } else {
        Class::Other
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct BuiltinId(pub(crate) u16);

include!("builtin_ids.rs");

impl BuiltinId {
    /// The id with this name, if the table has it.
    pub fn of(name: &str) -> Option<BuiltinId> {
        NAMES.binary_search(&name).ok().map(|i| BuiltinId(i as u16))
    }

    /// The id with this name, at compile time: a name the table does not have fails the build. For the
    /// registries, whose entries are listed by name.
    pub const fn must(name: &str) -> BuiltinId {
        let want = name.as_bytes();
        let mut i = 0;
        while i < NAMES.len() {
            let have = NAMES[i].as_bytes();
            if have.len() == want.len() {
                let mut j = 0;
                while j < have.len() && have[j] == want[j] {
                    j += 1;
                }
                if j == have.len() {
                    return BuiltinId(i as u16);
                }
            }
            i += 1;
        }
        panic!("not a builtin id: add it to the registry and regenerate builtin_ids.rs")
    }

    /// The name, as the catalog and the registries spell it: `Record.Insert#2`.
    pub fn name(self) -> &'static str {
        NAMES[self.0 as usize]
    }

    /// The method part of the name, for messages: `Insert` of `Record.Insert#2`.
    pub fn method(self) -> &'static str {
        let n = self.name();
        let after = n.split_once('.').map_or(n, |(_, m)| m);
        after.split('#').next().unwrap_or(after)
    }

    /// The position in the table: the index into per-id arrays.
    pub fn index(self) -> usize {
        self.0 as usize
    }

    pub fn class(self) -> Class {
        CLASSES[self.0 as usize]
    }

    /// How many ids there are.
    pub const fn count() -> usize {
        NAMES.len()
    }

    /// Every id, in table order.
    pub fn all() -> impl Iterator<Item = BuiltinId> {
        (0..NAMES.len() as u16).map(BuiltinId)
    }
}

impl std::fmt::Display for BuiltinId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.name())
    }
}

impl std::fmt::Debug for BuiltinId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "BuiltinId({})", self.name())
    }
}

/// A binary form (the cache) holds the index; a readable form (JSON dumps) holds the name.
impl Serialize for BuiltinId {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        if s.is_human_readable() {
            s.serialize_str(self.name())
        } else {
            s.serialize_u16(self.0)
        }
    }
}

impl<'de> Deserialize<'de> for BuiltinId {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        use serde::de::Error;
        if d.is_human_readable() {
            let name = String::deserialize(d)?;
            BuiltinId::of(&name).ok_or_else(|| D::Error::custom(format!("`{name}` is not a builtin id")))
        } else {
            let i = u16::deserialize(d)?;
            if (i as usize) < NAMES.len() {
                Ok(BuiltinId(i))
            } else {
                Err(D::Error::custom(format!("builtin id {i} is out of range")))
            }
        }
    }
}

/// The source of `builtin_ids.rs` for these names (sorted, unique).
pub fn render_table(names: &[String]) -> String {
    use std::fmt::Write;
    let mut out = String::new();
    out.push_str("// @generated by `cargo run -p al-builtins --example gen_builtin_ids`. Do not edit.\n");
    out.push_str(
        "// Every overload id of the catalog, the registered natives and the ids the lowering invents, sorted.\n\n",
    );
    let _ = writeln!(out, "pub(crate) const NAMES: [&str; {}] = [", names.len());
    for n in names {
        let _ = writeln!(out, "    \"{}\",", n.replace('\\', "\\\\").replace('"', "\\\""));
    }
    out.push_str("];\n\n");
    let _ = writeln!(out, "pub(crate) const CLASSES: [Class; {}] = [", names.len());
    for n in names {
        let _ = writeln!(out, "    Class::{},", class_of(n).variant());
    }
    out.push_str("];\n\n");
    out.push_str(
        "/// One constant per id, for `match`.\n#[allow(dead_code)]\npub mod ids {\n    use super::BuiltinId;\n",
    );
    let mut seen = std::collections::HashMap::new();
    for (i, n) in names.iter().enumerate() {
        let c: String = n
            .chars()
            .map(|c| {
                if c.is_ascii_alphanumeric() {
                    c.to_ascii_uppercase()
                } else {
                    '_'
                }
            })
            .collect();
        if let Some(prev) = seen.insert(c.clone(), n) {
            panic!("`{prev}` and `{n}` give the same constant name {c}");
        }
        let _ = writeln!(out, "    pub const {c}: BuiltinId = BuiltinId({i});");
    }
    out.push_str("}\n");
    out
}
